## ----constructed-dba-data-----------------------------------------------------------------------------------------------
dba_gc_ex001


## ----constructed-dba-run------------------------------------------------------------------------------------------------
dba_ex1_list <- extract_info(assignment = "diversity", dframe = dba_gc_ex001, 
                        demographic_cols = 2, skills = 3, self_formed_groups = 4)

dba_ex1_model <- prepare_model(dba_ex1_list, assignment = "diversity", 
                               w1 = 1.0, w2 = 0.0, 
                               n_topics = 2, nmin = 2, nmax = 2, rmin = 1, rmax = 1 )

dba_ex1_result <- solve_assignment(dba_ex1_model, "diversity", solver="glpk", 
                                   verbose=FALSE, 
                                   dframe = dba_gc_ex001,  group_names="groups")


## ----constructed-dba-2, echo=FALSE--------------------------------------------------------------------------------------
knitr::kable(dba_ex1_result$output, booktabs=TRUE,
             col.names = c("topic", "rep", "group", "id", "major", "skill"),
             caption = "The assigned groupings for the constructed DBA dataset. Students 2 and 4 have been assigned to topic 1 and students 1 and 3 to topic 2.") %>% 
  kableExtra::kable_styling(latex_options = c("hold_position"))


