## ----load-ay2520, include=FALSE-----------------------------------------------------------------------------------------
# Read student records with anonymous labels and course-role demand.
students_ay2520 <- read.csv("data/raw/ay2520/students.csv", stringsAsFactors = FALSE)
demand_ay2520 <- read.csv("data/raw/ay2520/demand.csv", stringsAsFactors = FALSE)
pref_long_ay2520 <- read.csv("data/raw/ay2520/preferences_long.csv", stringsAsFactors = FALSE)

# Use stable ordering so row and column positions have a fixed meaning.
students_ay2520 <- students_ay2520[order(students_ay2520$student_id), ]
demand_ay2520 <- demand_ay2520[order(demand_ay2520$course_code), ]

# Convert long-form preference records into matrix row and column indices.
pref_long_ay2520$i <- match(pref_long_ay2520$student_id, students_ay2520$student_id)
pref_long_ay2520$j <- match(pref_long_ay2520$course_code, demand_ay2520$course_code)

# Build the student-by-course preference matrix.
P_ay2520 <- matrix(-99L, nrow = nrow(students_ay2520), ncol = nrow(demand_ay2520))
P_ay2520[cbind(pref_long_ay2520$i, pref_long_ay2520$j)] <- pref_long_ay2520$pref_score

# Build the course-by-role demand matrix in the role order expected by the model.
D_ay2520 <- as.matrix(demand_ay2520[, c("TA", "GR", "E")])


## ----multirole-extract-info---------------------------------------------------------------------------------------------
df_multirole <- extract_info(
  assignment = "multirole",
  student_df = students_ay2520[, c("student_id", "year", "past_ta", "past_gr")],
  d_mat = D_ay2520, p_ta_mat = P_ay2520, e_mode = "none", C = 4)


## ----multirole-prepare-model--------------------------------------------------------------------------------------------
model_multirole <- prepare_model(df_list = df_multirole, 
                                 assignment = "multirole",
                                 alpha_ta = 2, alpha_gr = NULL, 
                                 beta_ta = 1, beta_gr = NULL, 
                                 phi = 1, rho_ta = 10, rho_gr = NULL, 
                                 protected_year_ta = 1, 
                                 ta_protected_max = 1, e_max = 1)


## ----multirole-solve-assignment-----------------------------------------------------------------------------------------
multirole_solution <- solve_assignment(model = model_multirole, 
                                       assignment = "multirole", 
                                       solver = "glpk",
                                       student_df = students_ay2520, 
                                       course_codes = demand_ay2520$course_code,
                                       name_col = "student_id", verbose = FALSE)


