## ----load-solver-runtime, include=FALSE---------------------------------------------------------------------------------
solver_runtime <- read.csv("data/derived/ay2520_solver_runtime.csv", check.names = FALSE)

runtime_summary <- solver_runtime %>%
  group_by(Solver) %>%
  summarise(runs = n(), objective = unique(Objective),
            mean_time = mean(Time_seconds),min_time = min(Time_seconds),
            max_time = max(Time_seconds), .groups = "drop")

glpk_runtime <- runtime_summary %>% filter(Solver == "glpk")
highs_runtime <- runtime_summary %>% filter(Solver == "highs")


